mod prepared;mod table_oracle;mod full_ic;mod walk;mod dense;mod linear;mod tail;mod pencil_fullnorm;mod pencil_tail;
use hec_native_ic::{counted,instance::pick_instance,rng::Rng,solve::Solver};
fn old_key<'a>(line:&'a str,key:&str)->Option<&'a str>{line.split_whitespace().find_map(|s|s.strip_prefix(&format!("{key}=")))}
fn main(){let old_walk=include_str!("../native-public-2lp-cost/CONTROL.txt");let old_pencils=include_str!("../native-pencil-tail-cost/CONTROL.txt");let mut calls=0;
 for line in include_str!("INSTANCES.tsv").lines().skip(1){counted::disable();let v:Vec<_>=line.split('\t').collect();let g:usize=v[0].parse().unwrap();let p:u64=v[1].parse().unwrap();let cc:u64=v[2].parse().unwrap();let ell:u64=v[3].parse().unwrap();let inst=pick_instance(p,g).unwrap();assert_eq!(inst.c,cc);assert_eq!(inst.ell,ell);assert_eq!(inst.curve.f.c[..inst.curve.f.n].iter().map(u64::to_string).collect::<Vec<_>>().join(","),v[4]);let mut rng=Rng::new(2026111800^p^((g as u64)<<32));
 for case in 0..2{let sm=if case==0{1}else{17};let d=inst.curve.mul(&inst.d1,sm);let k=1+rng.below(ell-1);let t=inst.curve.mul(&d,k);let seed=2026111800+case as u64;let mut prior=std::collections::BTreeMap::new();
 for rep in 0..2{let arms=if(case+rep)%2==0{[0,1,2,3,4,5]}else{[5,4,3,2,1,0]};for arm in arms{let name=["2lp","full_fast","full_dense","full_hybrid","pencil_fullnorm","pencil_tail"][arm];eprintln!("start g={g} p={p} case={case} arm={name} rep={rep}");counted::reset();walk::validate(&inst.curve,&d,&t,ell);let prepared=prepared::prepare(&inst.curve,false);
 let(answer,signature)=match arm{0=>{let r=walk::solve(&inst.curve,&d,&t,ell,&walk::Params{seed,limit:200000,audit_prefix:0},&prepared);(r.k,format!("trials={} rows={} lp_pivots={}",r.trials,r.full_rows,r.pivots))},1..=3=>{let mode=match arm{1=>Solver::Fast,2=>Solver::Dense,_=>Solver::Hybrid};let r=full_ic::solve_dlp(&inst.curve,&d,&t,ell,&full_ic::IcParams{seed,max_trials:200000,solver:mode,reference_oracle:false,..full_ic::IcParams::default()},&prepared);(r.k,format!("trials={} rows={} lp_pivots=0",r.trials,r.relations))},4=>{let r=pencil_fullnorm::solve(&inst.curve,&d,&t,ell,512,false,&prepared);(r.k,format!("report={r:?}"))},_=>{let r=pencil_tail::solve(&inst.curve,&d,&t,ell,512,false,&prepared);(r.k,format!("report={r:?}"))}};
 let counts=counted::snapshot();counted::disable();assert_eq!(answer,Some(k));assert_eq!(inst.curve.mul(&d,k),t);let lookup=(prepared.roots.sqrt_lookups.get(),prepared.roots.legendre_lookups.get(),prepared.roots.bytes());
 if arm<4{let line=old_walk.lines().find(|l|l.starts_with("OUTCOME ")&&old_key(l,"g")==Some(v[0])&&old_key(l,"p")==Some(v[1])&&old_key(l,"source_multiple")==Some(sm.to_string().as_str())&&old_key(l,"case")==Some(case.to_string().as_str())&&old_key(l,"arm")==Some(name)&&old_key(l,"rep")==Some("0")).unwrap();for field in["trials","rows","lp_pivots"]{assert_eq!(old_key(line,field),old_key(&signature,field));}}
 else{let line=old_pencils.lines().find(|l|l.starts_with("OUTCOME ")&&old_key(l,"g")==Some(v[0])&&old_key(l,"p")==Some(v[1])&&old_key(l,"sm")==Some(sm.to_string().as_str())&&old_key(l,"case")==Some(case.to_string().as_str())&&old_key(l,"arm")==Some(name)&&old_key(l,"rep")==Some("0")).unwrap();assert_eq!(line.split("report=").nth(1).unwrap(),signature.strip_prefix("report=").unwrap());}
 for(&modulus,values)in &counts{assert_eq!(values[8],2*values[7]+values[5]+values[6]);if modulus==ell{let data=if arm<4{old_walk}else{old_pencils};let line=data.lines().find(|l|l.starts_with("COUNT ")&&old_key(l,"g")==Some(v[0])&&old_key(l,"p")==Some(v[1])&&old_key(l,"source_multiple")==Some(sm.to_string().as_str())&&old_key(l,"case")==Some(case.to_string().as_str())&&old_key(l,"arm")==Some(name)&&old_key(l,"rep")==Some("0")&&old_key(l,"modulus")==Some(ell.to_string().as_str())).unwrap();let vals:Vec<u64>=line.split("vector=[").nth(1).unwrap().trim_end_matches(']').split(',').map(|s|s.trim().parse().unwrap()).collect();assert_eq!(values.as_slice(),vals.as_slice());}println!("COUNT g={g} p={p} source_multiple={sm} case={case} arm={name} rep={rep} modulus={modulus} vector={values:?}");}
 let state=(answer,signature.clone(),lookup,counts);if let Some(old)=prior.get(&arm){assert_eq!(old,&state);}else{prior.insert(arm,state);}println!("OUTCOME g={g} p={p} sm={sm} case={case} arm={name} rep={rep} sqrt_lookups={} legendre_lookups={} root_bytes={} {signature}",lookup.0,lookup.1,lookup.2);calls+=1;
 }} }}assert_eq!(calls,264);eprintln!("PASS complete_calls={calls} models=11 fixtures=22 six_arms_fresh_preparation=true old_outcome_streams_replay=true old_subgroup_vectors_unchanged=true native_answers=true repeat_vectors_and_lookup_counts_exact=true no_cross_call_cache=true no_wall_or_tenfold_claim=true");}
